TomoMod_RegisterLocale("enUS", {
    ["wn_404_tomohdv_buy_layout"] = "Fixed — TomoHDV V3.2 anchors quantity, total and status from the bottom of the item sheet. The complete direct-purchase workflow now stays clear of the buy button on ultrawide displays and at compact UI scales.",
    ["wn_404_tomohdv_buy_final_polish"] = "Changed — TomoHDV V3.3 arranges auction type and quantity, estimated total, status and confirmation into four compact bottom-aligned rows. The redundant title is gone, the total has more room and labels no longer stack at small or medium interface heights.",
    ["wn_404_nameplates_secret_power"] = "Fixed — Follower-dungeon role detection checks whether UnitPowerMax returned a protected value before comparing it. Unreadable mana safely falls back to the damage role instead of raising an error in restricted content.",
})

